// Vanilla JavaScript - GDPR Cookie Consent Implementation

// 1. COOKIE CONSENT BANNER (DIY)
// ===============================

// cookie-consent.js
(function() {
  'use strict';

  const CONSENT_COOKIE_NAME = 'gdpr_cookie_consent';
  const CONSENT_VERSION = '1.0';

  // Cookie categories
  const COOKIE_CATEGORIES = {
    essential: true,      // Always enabled
    functional: false,
    analytics: false,
    marketing: false
  };

  // Check if consent already given
  function hasConsent() {
    const consent = getCookie(CONSENT_COOKIE_NAME);
    return consent !== null;
  }

  // Get cookie value
  function getCookie(name) {
    const value = `; ${document.cookie}`;
    const parts = value.split(`; ${name}=`);
    if (parts.length === 2) {
      return parts.pop().split(';').shift();
    }
    return null;
  }

  // Set cookie
  function setCookie(name, value, days) {
    const date = new Date();
    date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
    const expires = `expires=${date.toUTCString()}`;
    document.cookie = `${name}=${value};${expires};path=/;SameSite=Lax`;
  }

  // Get consent preferences
  function getConsent() {
    const consent = getCookie(CONSENT_COOKIE_NAME);
    if (consent) {
      try {
        return JSON.parse(decodeURIComponent(consent));
      } catch (e) {
        return null;
      }
    }
    return null;
  }

  // Save consent
  function saveConsent(preferences) {
    const consent = {
      version: CONSENT_VERSION,
      timestamp: new Date().toISOString(),
      preferences: preferences
    };

    const value = encodeURIComponent(JSON.stringify(consent));
    setCookie(CONSENT_COOKIE_NAME, value, 365);

    // Enable cookies based on consent
    enableCookies(preferences);

    // Hide banner
    hideBanner();
  }

  // Enable cookies based on consent
  function enableCookies(preferences) {
    // Essential cookies always enabled

    // Analytics (Google Analytics example)
    if (preferences.analytics) {
      // Load Google Analytics
      window.dataLayer = window.dataLayer || [];
      function gtag(){dataLayer.push(arguments);}
      gtag('js', new Date());
      gtag('config', 'GA_MEASUREMENT_ID');
    }

    // Marketing cookies
    if (preferences.marketing) {
      // Load marketing scripts (Facebook Pixel, etc.)
      // Example: loadMarketingScripts();
    }
  }

  // Create banner HTML
  function createBanner() {
    const banner = document.createElement('div');
    banner.id = 'cookie-consent-banner';
    banner.innerHTML = `
      <div class="cookie-banner" role="dialog" aria-label="Cookie consent">
        <div class="cookie-banner-content">
          <h2>Cookie Consent</h2>
          <p>
            We use cookies to enhance your browsing experience, serve personalized 
            content, and analyze our traffic. By clicking "Accept All", you consent 
            to our use of cookies. See our 
            <a href="/privacy-policy" target="_blank">Privacy Policy</a> for details.
          </p>

          <div class="cookie-categories">
            <label>
              <input type="checkbox" id="essential" checked disabled>
              <strong>Essential Cookies (Required)</strong>
              <p>Necessary for website functionality</p>
            </label>

            <label>
              <input type="checkbox" id="functional">
              <strong>Functional Cookies</strong>
              <p>Remember your preferences</p>
            </label>

            <label>
              <input type="checkbox" id="analytics">
              <strong>Analytics Cookies</strong>
              <p>Help us understand how you use our site</p>
            </label>

            <label>
              <input type="checkbox" id="marketing">
              <strong>Marketing Cookies</strong>
              <p>Used for targeted advertising</p>
            </label>
          </div>

          <div class="cookie-banner-actions">
            <button id="accept-selected" class="btn-primary">Accept Selected</button>
            <button id="accept-all" class="btn-primary">Accept All</button>
            <button id="reject-all" class="btn-secondary">Reject All</button>
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(banner);

    // Attach event listeners
    document.getElementById('accept-all').addEventListener('click', () => {
      saveConsent({
        essential: true,
        functional: true,
        analytics: true,
        marketing: true
      });
    });

    document.getElementById('reject-all').addEventListener('click', () => {
      saveConsent({
        essential: true,
        functional: false,
        analytics: false,
        marketing: false
      });
    });

    document.getElementById('accept-selected').addEventListener('click', () => {
      saveConsent({
        essential: true,
        functional: document.getElementById('functional').checked,
        analytics: document.getElementById('analytics').checked,
        marketing: document.getElementById('marketing').checked
      });
    });
  }

  // Hide banner
  function hideBanner() {
    const banner = document.getElementById('cookie-consent-banner');
    if (banner) {
      banner.remove();
    }
  }

  // Show banner if no consent
  function init() {
    if (!hasConsent()) {
      createBanner();
    } else {
      // Load cookies based on existing consent
      const consent = getConsent();
      if (consent && consent.preferences) {
        enableCookies(consent.preferences);
      }
    }
  }

  // Initialize when DOM ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  // Expose global API
  window.CookieConsent = {
    getConsent: getConsent,
    updateConsent: saveConsent,
    showBanner: createBanner
  };
})();

