// 3. BLOCKING THIRD-PARTY SCRIPTS
// ================================

// Replace direct script tags with data attributes
// Before:
// <script src="https://www.googletagmanager.com/gtag/js?id=GA_ID"></script>

// After:
// <script type="text/plain" data-cookie-consent="analytics" 
//         src="https://www.googletagmanager.com/gtag/js?id=GA_ID"></script>

// Load scripts when consent given
function loadConsentedScripts() {
  const consent = window.CookieConsent.getConsent();
  if (!consent) return;

  const scripts = document.querySelectorAll('script[data-cookie-consent]');
  scripts.forEach(script => {
    const category = script.getAttribute('data-cookie-consent');
    if (consent.preferences[category]) {
      // Create new script element with proper type
      const newScript = document.createElement('script');
      newScript.src = script.src;
      newScript.type = 'text/javascript';
      document.head.appendChild(newScript);
    }
  });
}

