// React - Cookie Consent Component

import React, { useState, useEffect } from 'react';
import './CookieConsent.css';

const CONSENT_COOKIE_NAME = 'gdpr_cookie_consent';
const CONSENT_VERSION = '1.0';

function CookieConsent() {
  const [showBanner, setShowBanner] = useState(false);
  const [preferences, setPreferences] = useState({
    essential: true,
    functional: false,
    analytics: false,
    marketing: false
  });

  useEffect(() => {
    // Check if consent already given
    const consent = getConsent();
    if (!consent) {
      setShowBanner(true);
    } else {
      // Enable cookies based on existing consent
      enableCookies(consent.preferences);
    }
  }, []);

  function getCookie(name) {
    const value = `; ${document.cookie}`;
    const parts = value.split(`; ${name}=`);
    if (parts.length === 2) {
      return parts.pop().split(';').shift();
    }
    return null;
  }

  function setCookie(name, value, days) {
    const date = new Date();
    date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
    const expires = `expires=${date.toUTCString()}`;
    document.cookie = `${name}=${value};${expires};path=/;SameSite=Lax;Secure`;
  }

  function getConsent() {
    const consent = getCookie(CONSENT_COOKIE_NAME);
    if (consent) {
      try {
        return JSON.parse(decodeURIComponent(consent));
      } catch (e) {
        return null;
      }
    }
    return null;
  }

  function saveConsent(prefs) {
    const consent = {
      version: CONSENT_VERSION,
      timestamp: new Date().toISOString(),
      preferences: prefs
    };

    const value = encodeURIComponent(JSON.stringify(consent));
    setCookie(CONSENT_COOKIE_NAME, value, 365);

    enableCookies(prefs);
    setShowBanner(false);
  }

  function enableCookies(prefs) {
    // Analytics
    if (prefs.analytics && window.gtag) {
      window.gtag('consent', 'update', {
        'analytics_storage': 'granted'
      });
    }

    // Marketing
    if (prefs.marketing && window.gtag) {
      window.gtag('consent', 'update', {
        'ad_storage': 'granted'
      });
    }
  }

  const handleAcceptAll = () => {
    saveConsent({
      essential: true,
      functional: true,
      analytics: true,
      marketing: true
    });
  };

  const handleRejectAll = () => {
    saveConsent({
      essential: true,
      functional: false,
      analytics: false,
      marketing: false
    });
  };

  const handleAcceptSelected = () => {
    saveConsent(preferences);
  };

  const handlePreferenceChange = (category) => {
    setPreferences(prev => ({
      ...prev,
      [category]: !prev[category]
    }));
  };

  if (!showBanner) return null;

  return (
    <div className="cookie-consent-overlay" role="dialog" aria-label="Cookie consent">
      <div className="cookie-consent-banner">
        <h2>Cookie Consent</h2>
        <p>
          We use cookies to enhance your experience. By continuing to visit this site 
          you agree to our use of cookies. Learn more in our{' '}
          <a href="/privacy-policy" target="_blank" rel="noopener">Privacy Policy</a>.
        </p>

        <div className="cookie-categories">
          <label>
            <input
              type="checkbox"
              checked={preferences.essential}
              disabled
            />
            <div>
              <strong>Essential Cookies (Required)</strong>
              <p>Necessary for website functionality</p>
            </div>
          </label>

          <label>
            <input
              type="checkbox"
              checked={preferences.functional}
              onChange={() => handlePreferenceChange('functional')}
            />
            <div>
              <strong>Functional Cookies</strong>
              <p>Remember your preferences and settings</p>
            </div>
          </label>

          <label>
            <input
              type="checkbox"
              checked={preferences.analytics}
              onChange={() => handlePreferenceChange('analytics')}
            />
            <div>
              <strong>Analytics Cookies</strong>
              <p>Help us improve our website</p>
            </div>
          </label>

          <label>
            <input
              type="checkbox"
              checked={preferences.marketing}
              onChange={() => handlePreferenceChange('marketing')}
            />
            <div>
              <strong>Marketing Cookies</strong>
              <p>Used for personalized advertising</p>
            </div>
          </label>
        </div>

        <div className="cookie-actions">
          <button onClick={handleAcceptSelected} className="btn-primary">
            Accept Selected
          </button>
          <button onClick={handleAcceptAll} className="btn-primary">
            Accept All
          </button>
          <button onClick={handleRejectAll} className="btn-secondary">
            Reject All
          </button>
        </div>
      </div>
    </div>
  );
}

export default CookieConsent;

