// React Testing Library tests
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import CookieConsent from './CookieConsent';

beforeEach(() => {
  // Clear cookies
  document.cookie.split(';').forEach(c => {
    document.cookie = c.split('=')[0] + '=;expires=Thu, 01 Jan 1970 00:00:00 UTC;path=/';
  });
});

test('shows banner when no consent', () => {
  render(<CookieConsent />);
  expect(screen.getByText(/Cookie Consent/i)).toBeInTheDocument();
});

test('hides banner after accepting all', async () => {
  render(<CookieConsent />);

  const acceptButton = screen.getByText(/Accept All/i);
  fireEvent.click(acceptButton);

  await waitFor(() => {
    expect(screen.queryByText(/Cookie Consent/i)).not.toBeInTheDocument();
  });
});

test('saves consent preferences', async () => {
  render(<CookieConsent />);

  fireEvent.click(screen.getByText(/Accept All/i));

  await waitFor(() => {
    const cookies = document.cookie;
    expect(cookies).toContain('gdpr_cookie_consent');
  });
});

