// Playwright test for cookie consent
import { test, expect } from '@playwright/test';

test('cookie consent banner appears', async ({ page }) => {
  // Clear cookies
  await page.context().clearCookies();

  await page.goto('https://your-domain.com');

  // Banner should appear
  await expect(page.locator('.cookie-banner')).toBeVisible();

  // No non-essential cookies before consent
  const cookies = await page.context().cookies();
  const nonEssential = cookies.filter(c => 
    !c.name.includes('session') && !c.name.includes('csrf')
  );
  expect(nonEssential.length).toBe(0);
});

test('accept all sets cookies', async ({ page }) => {
  await page.context().clearCookies();
  await page.goto('https://your-domain.com');

  // Accept all
  await page.click('button:has-text("Accept All")');

  // Banner should disappear
  await expect(page.locator('.cookie-banner')).toBeHidden();

  // Consent cookie should be set
  const cookies = await page.context().cookies();
  const consentCookie = cookies.find(c => c.name === 'gdpr_cookie_consent');
  expect(consentCookie).toBeDefined();
});
